// Single observation-qualification guard (root cause 2): a current target
// observation is only valid when the presented snapshot actually has a
// candidate, its ground is valid, and the authoritative ground verifier is
// available. A ready baseline or a fresh state alone never substitutes for a
// current candidate observation; unknown sensors must show unknown/null.
function observationQualified(snapshot, state) {
  if (!snapshot || typeof snapshot !== "object") return { ok: false, reason: "no_snapshot" };
  if (!Array.isArray(snapshot.candidates) || !snapshot.candidates.length)
    return { ok: false, reason: "no_candidate" };
  if (!state || typeof state !== "object") return { ok: false, reason: "no_state" };
  // The state and the presented snapshot must belong to the same current
  // binding: session/epoch/source seq-stamp/frame and, when the state carries
  // it, snapshot_id and the calibration binding (id/schema, GDID lives at the
  // state top level). A mismatch is a current-observation loss, not a normal
  // scene -- even when both sides share the same wrong value (V06/C04/C06).
  if (snapshot.session_id != null && state.session_id != null &&
      snapshot.session_id !== state.session_id)
    return { ok: false, reason: "session_mismatch" };
  if (isInt(snapshot.time_epoch) && isInt(state.time_epoch) &&
      snapshot.time_epoch !== state.time_epoch)
    return { ok: false, reason: "epoch_mismatch" };
  if (snapshot.snapshot_id != null && state.snapshot_id != null &&
      snapshot.snapshot_id !== state.snapshot_id)
    return { ok: false, reason: "snapshot_id_mismatch" };
  var ss = snapshot.source, ts = state.source;
  if (ss && ts) {
    var ssk = sourceKey(ss), tsk = sourceKey(ts);
    if (ssk !== null && tsk !== null && ssk !== tsk)
      return { ok: false, reason: "source_frame_mismatch" };
    if (ss.frame_id != null && ts.frame_id != null && ss.frame_id !== ts.frame_id)
      return { ok: false, reason: "source_frame_mismatch" };
  }
  var cal = snapshot.calibration || {}, tcal = state.calibration || {};
  if (cal.schema_version !== 1 ||
      (tcal.schema_version != null && tcal.schema_version !== 1))
    return { ok: false, reason: "unsupported_schema" };
  if (cal.calibration_id != null && tcal.calibration_id != null &&
      cal.calibration_id !== tcal.calibration_id)
    return { ok: false, reason: "calibration_id_mismatch" };
  var coord = snapshot.coordinate || {};
  var sgd = coord.ground_derived_id != null ? coord.ground_derived_id : cal.ground_derived_id;
  if (sgd != null && state.ground_derived_id != null && sgd !== state.ground_derived_id)
    return { ok: false, reason: "ground_derived_id_mismatch" };
  var gstatus = cal.ground_status != null ? cal.ground_status
    : (snapshot.ground && snapshot.ground.status != null ? snapshot.ground.status : "unknown");
  if (gstatus !== "valid") return { ok: false, reason: "ground_" + gstatus };
  var sq = state.sensor_quality;
  if (sq && typeof sq === "object") {
    if (sq.ground_verifier_available === false)
      return { ok: false, reason: "verifier_unavailable" };
    var gm = sq.ground_monitor;
    if (gm && typeof gm === "object" && gm.status != null && gm.status !== "ok")
      return { ok: false, reason: "ground_monitor_" + gm.status };
  }
  return { ok: true, reason: "ok" };
}

