check('V09','legacy no calibration no ground raw first selection preserved',()=>{const f=fixture();f.snap.calibration={calibration_id:null,schema_version:null,ground_status:'unknown',ground_derived_id:null};f.snap.coordinate={source_frame:'innolidar',ground_relative_available:false,ground_derived_id:null,horizontal_basis:'raw_xy_uncalibrated'};f.snap.ground=null;f.snap.ground_render=null;Object.assign(f.state,{calibration:clone(f.snap.calibration),coordinate:clone(f.snap.coordinate),ground:null,ground_derived_id:null,sensor_quality:{ground_valid:false},track_id:null,track_status:'unselected',fall_status:'unknown',position_source_m:null,bbox_source_min_m:null,bbox_source_max_m:null,center_ground_m:null,selection_version:0});const w=worldWith(f);w.context.__review.hfRenderCandidates();const n=w.sent.length;w.$('hfCands').children.at(-1).onclick();assert.strictEqual(w.sent.length,n+1);});
check('V06','one-sided missing GDID cannot match known state binding',()=>{const f=fixture();f.snap.coordinate.ground_derived_id=null;f.snap.calibration.ground_derived_id=null;f.snap.coordinate.ground=null;f.snap.ground_render=null;const w=worldWith(f);assert.strictEqual(w.$('hfFall').textContent,'unknown');});
fs.writeFileSync(path.join(__dirname,'r4_selfcheck_results.json'),JSON.stringify(results,null,2));
for(const r of results)console.log(r.result+' '+r.id+' '+r.name+(r.error?' :: '+r.error:''));
console.log(JSON.stringify({pass:results.filter(x=>x.result==='PASS').length,fail:results.filter(x=>x.result==='FAIL').length}));
process.exitCode=results.some(r=>r.result==='FAIL')?1:0;

