check('V06','paired new calibration/GDID both sides recovers current target',()=>{const f=fixture();f.snap.calibration.calibration_id='cal2';f.snap.calibration.ground_derived_id='gd2';f.snap.coordinate.ground_derived_id='gd2';f.snap.coordinate.ground.calibration_id='cal2';f.snap.coordinate.ground.ground_derived_id='gd2';f.snap.ground_render.calibration_id='cal2';f.snap.ground_render.ground_derived_id='gd2';f.snap.ground.ground_derived_id='gd2';f.state.calibration.calibration_id='cal2';f.state.calibration.ground_derived_id='gd2';f.state.ground_derived_id='gd2';const w=worldWith(f);assert.strictEqual(w.$('hfFall').textContent,'upright');});
check('V06','both-missing nullable GDID binding stays upright (legacy)',()=>{const f=fixture();f.snap.coordinate.ground_derived_id=null;f.snap.calibration.ground_derived_id=null;f.snap.coordinate.ground.ground_derived_id=null;f.snap.ground_render.ground_derived_id=null;f.state.ground_derived_id=null;const w=worldWith(f);assert.strictEqual(w.$('hfFall').textContent,'upright');});
check('V07','predicted pose is not re-matched to a current candidate',()=>{const f=fixture();f.state.position_predicted=true;f.state.position_source_m=[9,0,-.5];f.state.bbox_source_min_m=[8.8,-.2,-1];f.state.bbox_source_max_m=[9.2,.2,.5];const w=worldWith(f);assert.notStrictEqual(w.$('hfFall').textContent,'unknown');});
fs.writeFileSync(path.join(__dirname,'r4_selfcheck_results.json'),JSON.stringify(results,null,2));

